  while (p !== -1 && nxt[p * 26 + c] === -1) { nxt[p * 26 + c] = cur; p = link[p]; }
  if (p === -1) link[cur] = 0;
  else {
    const q = nxt[p * 26 + c];
    if (len[p] + 1 === len[q]) link[cur] = q;
    else {
      const clone = size++;
      len[clone] = len[p] + 1;
      for (let k = 0; k < 26; k++) nxt[clone * 26 + k] = nxt[q * 26 + k];
      link[clone] = link[q];
      while (p !== -1 && nxt[p * 26 + c] === q) { nxt[p * 26 + c] = clone; p = link[p]; }
      link[q] = clone;
