import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine().trim();
        String t = br.readLine().trim();
        int maxStates = 2 * s.length() + 2;
        int[][] nxt = new int[maxStates][26];
        for (int[] row : nxt) Arrays.fill(row, -1);
        int[] link = new int[maxStates];
        int[] len = new int[maxStates];
        link[0] = -1;
        int size = 1, last = 0;
        for (int i = 0; i < s.length(); i++) {
            int c = s.charAt(i) - 'a';
            int cur = size++;
            len[cur] = len[last] + 1;
            int p = last;
            while (p != -1 && nxt[p][c] == -1) { nxt[p][c] = cur; p = link[p]; }
            if (p == -1) link[cur] = 0;
            else {
                int q = nxt[p][c];
                if (len[p] + 1 == len[q]) link[cur] = q;
                else {
                    int clone = size++;
                    len[clone] = len[p] + 1;
                    nxt[clone] = nxt[q].clone();
                    link[clone] = link[q];
                    while (p != -1 && nxt[p][c] == q) { nxt[p][c] = clone; p = link[p]; }
                    link[q] = clone;
                    link[cur] = clone;
                }
            }
            last = cur;
        }
        int v = 0, l = 0, best = 0;
        for (int i = 0; i < t.length(); i++) {
            int c = t.charAt(i) - 'a';
            while (v != 0 && nxt[v][c] == -1) { v = link[v]; l = len[v]; }
            if (nxt[v][c] != -1) { v = nxt[v][c]; l++; }
            best = Math.max(best, l);
        }
        System.out.println(best);
    }
}

