#include <bits/stdc++.h>
using namespace std;
int main() {
    string s, t;
    cin >> s >> t;
    int maxStates = 2 * s.size() + 2;
    vector<array<int, 26>> nxt(maxStates);
    for (auto &row : nxt) row.fill(-1);
    vector<int> link(maxStates, 0), len(maxStates, 0);
    link[0] = -1;
    int size = 1, last = 0;
    for (char ch : s) {
        int c = ch - 'a';
        int cur = size++;
        len[cur] = len[last] + 1;
        int p = last;
        while (p != -1 && nxt[p][c] == -1) { nxt[p][c] = cur; p = link[p]; }
        if (p == -1) link[cur] = 0;
        else {
            int q = nxt[p][c];
            if (len[p] + 1 == len[q]) link[cur] = q;
            else {
                int clone = size++;
                len[clone] = len[p] + 1;
                nxt[clone] = nxt[q];
                link[clone] = link[q];
                while (p != -1 && nxt[p][c] == q) { nxt[p][c] = clone; p = link[p]; }
                link[q] = link[cur] = clone;
            }
        }
        last = cur;
    }
    int v = 0, l = 0, best = 0;
    for (char ch : t) {
        int c = ch - 'a';
        while (v != 0 && nxt[v][c] == -1) { v = link[v]; l = len[v]; }
        if (nxt[v][c] != -1) { v = nxt[v][c]; l++; }
        best = max(best, l);
    }
    cout << best << endl;
    return 0;
}
